ci.yml.plan:
runs-on: ubuntu-latest
timeout-minutes: 5
outputs:
  tier: ${{ steps.plan.outputs.tier }}
  suites: ${{ steps.plan.outputs.suites }}
  legs: ${{ steps.plan.outputs.legs }}
steps:
  - uses: actions/checkout@v4
    with:
      fetch-depth: 0

  - name: the planner can say no (tests/ci-plan)
    run: |
      tests/ci-plan
      python3 -I tests/ci-retry.py
      python3 -I tests/mpx2-heap.d/budget.py
      python3 -I tests/ci-budgets.py
      tests/fetch-retry-selftest
      python3 -I tests/usb-session-selftest
      python3 -I tests/pipe-shape-selftest

  - name: the plan
    id: plan
    env:
      EVENT: ${{ github.event_name }}
      ACTION: ${{ github.event.action }}
      LABEL: ${{ github.event.label.name }}
      LABELS: ${{ join(github.event.pull_request.labels.*.name, ',') }}
      BASE: ${{ github.event.pull_request.base.sha }}
      HEAD: ${{ github.sha }}
      IN_TIER: ${{ inputs.tier }}
      IN_SUITES: ${{ inputs.suites }}
    run: tools/ci-plan --github-output "$GITHUB_OUTPUT"
